int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input_file> <word_to_search>\n";
        return 1;
    }

    std::string input_file = argv[1];
    std::string word_to_search = argv[2];

