        std::cerr << "Error opening file: " << input_file << "\n";
        return 1;
    }

    std::string line;
    int count = 0;

    while (std::getline(input, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);
        size_t pos = 0;
        while ((pos = line.find(word_to_search, pos)) != std::string::npos) {
            count++;
            pos += word_to_search.length();
        }
    }

    input.close();

    std::cout << "Word \"" << word_to_search << "\" appears " << count << " times in " << input_file << ".\n";

    return 0;
}
```

